    표8_상담적용: [
        {"상황":"영적 공격으로 두려움과 불안을 느끼는 성도", "성경원리":"의의 병기를 좌우에 가지고 있는 성도는 어느 방향에서 오는 공격도 막을 수 있음. 하나님의 능력이 함께함 (고후 6:7, 엡 6:10-17)", "실제적용":"구체적인 영적 공격의 상황을 파악하고, 그에 맞는 말씀을 찾아 선포하며 기도로 하나님의 능력을 구하도록 안내"},
        {"상황":"설교 준비가 두려워 말씀을 선포하기를 어려워하는 초임 사역자", "성경원리":"진리의 말씀과 하나님의 능력이 사역의 무기임. 내 능력이 아닌 하나님의 능력에 의존할 때 담대해질 수 있음 (고후 6:7, 고전 2:1-4)", "실제적용":"완벽한 기술보다 진리에 충실한 선포가 중요함을 격려하며, 하나님의 능력을 구하는 기도로 시작하도록 안내"},
        {"상황":"이단의 공격에 흔들리는 성도", "성경원리":"진리의 말씀이 이단과 거짓 교훈을 물리치는 무기임. 말씀을 더 깊이 알수록 속임에서 자유로워짐 (고후 6:7, 히 4:12)", "실제적용":"이단의 주장과 성경의 진리를 직접 대조하여 공부하게 하고, 말씀 훈련을 통해 스스로 분별할 수 있도록 교육"}
    ],
    표9_교차참조: [
        {"구절":"사 11:4", "연결점":"그 입의 막대기로 세상을 치며 입술의 기운으로 악인을 죽일 것이며 - 말씀이 무기가 됨", "구분":"구약"},
        {"구절":"슥 4:6", "연결점":"이는 힘으로 되지 아니하며 능으로 되지 아니하고 오직 나의 신으로 되느니라 - 하나님의 능력의 원천", "구분":"구약"},
        {"구절":"시 149:6", "연결점":"그들의 입에는 하나님에 대한 찬양이 있고 그들의 손에는 두 날 가진 칼이 있도다 - 영적 무기의 이미지", "구분":"구약"},
        {"구절":"사 49:2", "연결점":"내 입을 날카로운 칼같이 만드시고 - 말씀의 검 이미지", "구분":"구약"},
        {"구절":"엡 6:17", "연결점":"구원의 투구와 성령의 검 곧 하나님의 말씀을 가지라 - 진리의 말씀이 성령의 검임", "구분":"신약"},
        {"구절":"히 4:12", "연결점":"하나님의 말씀은 살아 있고 활력이 있어 좌우에 날선 어떤 검보다도 예리하며 - 말씀의 능력", "구분":"신약"},
        {"구절":"고후 10:4-5", "연결점":"우리의 싸우는 병기는 육체에 속한 것이 아니요 오직 하나님 앞에서 강력하여 견고한 진을 파하는 것이라", "구분":"신약"},
        {"구절":"롬 1:16", "연결점":"내가 복음을 부끄러워하지 아니하노니 이 복음은 모든 믿는 자에게 구원을 주시는 하나님의 능력이 됨이라", "구분":"신약"}
    ]
